<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Order; use App\Models\User; use Illuminate\Http\Request;
class AdminCustomerController extends Controller { public function index(Request $r) { $q=User::whereHas('roles',fn($q)=>$q->where('slug','customer')); if($s=$r->string('search')->toString())$q->where(fn($x)=>$x->where('name','like','%'.$s.'%')->orWhere('email','like','%'.$s.'%')->orWhere('phone','like','%'.$s.'%')); return response()->json($q->latest()->paginate(20)); } public function show(User $customer) { $orders=Order::where('user_id',$customer->id)->with('items')->latest()->get(); return response()->json(['data'=>['customer'=>$customer,'orders'=>$orders,'summary'=>['orders_count'=>$orders->count(),'total_spent'=>$orders->where('status','completed')->sum('grand_total')],'addresses'=>$customer->addresses,'wishlists'=>$customer->wishlists()->with('book')->get()]]); } }
